import React, { useEffect, useState } from 'react';
import axios from 'axios';

export default function App() {
  const [logs, setLogs] = useState([]);

  useEffect(() => {
    // placeholder: connect to backend /api/v1/logs (not implemented)
    setLogs([]);
  }, []);

  return (
    <div style={{ padding: 24, fontFamily: 'Arial, sans-serif' }}>
      <h1>Guardian Admin Dashboard</h1>
      <p>Audit logs will appear here.</p>
      <table border="1" cellPadding="8" style={{ borderCollapse: 'collapse', width: '100%' }}>
        <thead><tr><th>ID</th><th>Original</th><th>Sanitized</th><th>PII</th><th>NSFW</th><th>Timestamp</th></tr></thead>
        <tbody>
          {logs.length === 0 ? <tr><td colSpan="6">No logs (connect backend)</td></tr> : logs.map(l => (
            <tr key={l.id}><td>{l.id}</td><td>{l.original}</td><td>{l.sanitized}</td><td>{l.piiDetected ? 'Y' : 'N'}</td><td>{l.nsfwDetected ? 'Y' : 'N'}</td><td>{l.timestamp}</td></tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
